   274→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
   275→	if session == nil {
   276→		return nil, errors.New("session is nil")
   277→	}
   278→
   279→	if len(session.NativeData) == 0 {
   280→		return nil, errors.New("session has no native data")
