   208→// ReadSession reads a session from Claude's storage (JSONL transcript file).
   209→// The session data is stored in NativeData as raw JSONL bytes.
   210→// ModifiedFiles is computed by parsing the transcript.
   211→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
   212→	if input.SessionRef == "" {
   213→		return nil, errors.New("session reference (transcript path) is required")
   214→	}
   215→
   216→	// Read the raw JSONL file
   217→	data, err := os.ReadFile(input.SessionRef)
   218→	if err != nil {
   219→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   220→	}
   221→
   222→	// Parse to extract computed fields
   223→	lines, err := ParseTranscript(data)
   224→	if err != nil {
   225→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
   226→	}
   227→
   228→	return &agent.AgentSession{
   229→		SessionID:     input.SessionID,
   230→		AgentName:     c.Name(),
   231→		SessionRef:    input.SessionRef,
   232→		StartTime:     time.Now(),
   233→		NativeData:    data,
   234→		ModifiedFiles: ExtractModifiedFiles(lines),
   235→	}, nil
   236→}
