   238→// WriteSession writes a session to Claude's storage (JSONL transcript file).
   239→// Uses the NativeData field which contains raw JSONL bytes.
   240→// The session must have been created by Claude Code (AgentName check).
   241→func (c *ClaudeCodeAgent) WriteSession(session *agent.AgentSession) error {
   242→	if session == nil {
   243→		return errors.New("session is nil")
   244→	}
   245→
   246→	// Verify this session belongs to Claude Code
   247→	if session.AgentName != "" && session.AgentName != c.Name() {
   248→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
   249→	}
   250→
   251→	if session.SessionRef == "" {
   252→		return errors.New("session reference (transcript path) is required")
   253→	}
   254→
   255→	if len(session.NativeData) == 0 {
   256→		return errors.New("session has no native data to write")
   257→	}
   258→
   259→	// Write the raw JSONL data
   260→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
   261→		return fmt.Errorf("failed to write transcript: %w", err)
   262→	}
   263→
   264→	return nil
   265→}
