   272→// Session helper methods - work on AgentSession with Claude's native JSONL data
   273→
   274→// GetLastUserPrompt extracts the last user prompt from the session.
   275→// Requires NativeData to be populated (call ReadSession first).
   276→func (c *ClaudeCodeAgent) GetLastUserPrompt(session *agent.AgentSession) string {
   277→	if session == nil || len(session.NativeData) == 0 {
   278→		return ""
   279→	}
   280→
   281→	lines, err := ParseTranscript(session.NativeData)
   282→	if err != nil {
   283→		return ""
   284→	}
   285→
   286→	return ExtractLastUserPrompt(lines)
   287→}
   288→
   289→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
   290→// This is used for rewind operations to restore transcript state.
   291→// Requires NativeData to be populated.
   292→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
   293→	if session == nil {
   294→		return nil, errors.New("session is nil")
   295→	}
   296→
   297→	if len(session.NativeData) == 0 {
   298→		return nil, errors.New("session has no native data")
   299→	}
   300→
   301→	if uuid == "" {
   302→		// No truncation needed, return copy
   303→		return &agent.AgentSession{
   304→			SessionID:     session.SessionID,
   305→			AgentName:     session.AgentName,
   306→			RepoPath:      session.RepoPath,
   307→			SessionRef:    session.SessionRef,
   308→			StartTime:     session.StartTime,
   309→			NativeData:    session.NativeData,
   310→			ModifiedFiles: session.ModifiedFiles,
   311→		}, nil
   312→	}
   313→
   314→	// Parse, truncate, re-serialize
   315→	lines, err := ParseTranscript(session.NativeData)
   316→	if err != nil {
   317→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
   318→	}
   319→
   320→	truncated := TruncateAtUUID(lines, uuid)
   321→
   322→	newData, err := SerializeTranscript(truncated)
   323→	if err != nil {
   324→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
   325→	}
   326→
   327→	return &agent.AgentSession{
   328→		SessionID:     session.SessionID,
   329→		AgentName:     session.AgentName,
   330→		RepoPath:      session.RepoPath,
   331→		SessionRef:    session.SessionRef,
   332→		StartTime:     session.StartTime,
   333→		NativeData:    newData,
   334→		ModifiedFiles: ExtractModifiedFiles(truncated),
   335→	}, nil
   336→}
