   338→// FindCheckpointUUID finds the UUID of the message containing the tool_result
   339→// for the given tool use ID. Used for task checkpoint rewind.
   340→// Returns the UUID and true if found, empty string and false otherwise.
   341→func (c *ClaudeCodeAgent) FindCheckpointUUID(session *agent.AgentSession, toolUseID string) (string, bool) {
   342→	if session == nil || len(session.NativeData) == 0 {
   343→		return "", false
   344→	}
   345→
   346→	lines, err := ParseTranscript(session.NativeData)
   347→	if err != nil {
   348→		return "", false
   349→	}
