   354→// ReadSessionFromPath is a convenience method that reads a session directly from a file path.
   355→// This is useful when you have the path but not a HookInput.
   356→func (c *ClaudeCodeAgent) ReadSessionFromPath(transcriptPath, sessionID string) (*agent.AgentSession, error) {
   357→	return c.ReadSession(&agent.HookInput{
   358→		SessionID:  sessionID,
   359→		SessionRef: transcriptPath,
   360→	})
