   363→// SanitizePathForClaude converts a path to Claude's project directory format.
   364→// Claude replaces any non-alphanumeric character with a dash.
   365→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
   366→
   367→func SanitizePathForClaude(path string) string {
   368→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
   369→}
   370→
   371→// TranscriptAnalyzer interface implementation
   372→
   373→// GetTranscriptPosition returns the current line count of a Claude Code transcript.
   374→// Claude Code uses JSONL format, so position is the number of lines.
   375→// This is a lightweight operation that only counts lines without parsing JSON.
   376→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
   377→// Returns 0 if the file doesn't exist or is empty.
   378→func (c *ClaudeCodeAgent) GetTranscriptPosition(path string) (int, error) {
   379→	if path == "" {
   380→		return 0, nil
   381→	}
   382→
   383→	file, err := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
   384→	if err != nil {
   385→		if os.IsNotExist(err) {
   386→			return 0, nil
   387→		}
   388→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
   389→	}
   390→	defer file.Close()
   391→
   392→	reader := bufio.NewReader(file)
   393→	lineCount := 0
   394→
   395→	for {
   396→		_, err := reader.ReadBytes('\n')
   397→		if err != nil {
   398→			if err == io.EOF {
   399→				break
   400→			}
   401→			return 0, fmt.Errorf("failed to read transcript: %w", err)
   402→		}
   403→		lineCount++
   404→	}
   405→
   406→	return lineCount, nil
   407→}
   408→
   409→// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
   410→// For Claude Code (JSONL format), offset is the starting line number.
   411→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
   412→// Returns:
   413→//   - files: list of file paths modified by Claude (from Write/Edit tools)
   414→//   - currentPosition: total number of lines in the file
   415→//   - error: any error encountered during reading
   416→func (c *ClaudeCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
   417→	if path == "" {
   418→		return nil, 0, nil
   419→	}
   420→
   421→	file, openErr := os.Open(path) //nolint:gosec // Path comes from Claude Code transcript location
   422→	if openErr != nil {
   423→		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
   424→	}
   425→	defer file.Close()
   426→
   427→	reader := bufio.NewReader(file)
   428→	var lines []TranscriptLine
   429→	lineNum := 0
   430→
   431→	for {
   432→		lineData, readErr := reader.ReadBytes('\n')
   433→		if readErr != nil && readErr != io.EOF {
   434→			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
   435→		}
   436→
   437→		if len(lineData) > 0 {
   438→			lineNum++
   439→			if lineNum > startOffset {
   440→				var line TranscriptLine
   441→				if parseErr := json.Unmarshal(lineData, &line); parseErr == nil {
   442→					lines = append(lines, line)
   443→				}
   444→				// Skip malformed lines silently
   445→			}
   446→		}
   447→
   448→		if readErr == io.EOF {
   449→			break
   450→		}
   451→	}
   452→
   453→	return ExtractModifiedFiles(lines), lineNum, nil
   454→}
   455→
   456→// TranscriptChunker interface implementation
   457→
   458→// ChunkTranscript splits a JSONL transcript at line boundaries.
   459→// Claude Code uses JSONL format (one JSON object per line), so chunking
   460→// is done at newline boundaries to preserve message integrity.
   461→func (c *ClaudeCodeAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
   462→	chunks, err := agent.ChunkJSONL(content, maxSize)
   463→	if err != nil {
   464→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
   465→	}
   466→	return chunks, nil
   467→}
   468→
   469→// ReassembleTranscript concatenates JSONL chunks with newlines.
   470→//
   471→//nolint:unparam // error return is required by interface, kept for consistency
   472→func (c *ClaudeCodeAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
   473→	return agent.ReassembleJSONL(chunks), nil
   474→}
